module min_cost_tour (\n  input clk,\n  input rst_n,\n  input start,\n  input [2:0] flight_count,\n  input [7:0] flight_seq,\n  input [7:0] price_ow_12,\n  input [7:0] price_ow_21,\n  input [7:0] price_rt_12,\n  input [7:0] price_rt_21,\n  output reg [15:0] result,\n  output reg done\n);\n  localparam MAX_OPEN = 8;\n  localparam INF = 16'hFFFF;\n  localparam [1:0] IDLE = 2'd0;\n  localparam [1:0] PROCESS = 2'd1;\n  localparam [1:0] DONE_STATE = 2'd2;\n\n  reg [1:0] state, next_state;\n  reg [2:0] flight_index;\n  reg [15:0] dp [0:MAX_OPEN][0:MAX_OPEN];\n  reg [15:0] new_dp [0:MAX_OPEN][0:MAX_OPEN];\n  reg processing;\n\n  integer i,j,k;\n\n  always @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n      state <= IDLE;\n      done <= 1'b0;\n      result <= 16'd0;\n      flight_index <= 3'd0;\n      processing <= 1'b0;\n\n      for (i = 0; i <= MAX_OPEN; i = i + 1) begin\n        for (j = 0; j <= MAX_OPEN; j = j + 1) begin\n          dp[i][j] <= INF;\n        end\n      end\n      dp[0][0] <= 16'd0;\n    end else begin\n      case (state)\n        IDLE: begin\n          done <= 1'b0;\n          if (start) begin\n            flight_index <= 3'd0;\n            processing <= 1'b1;\n            for (i = 0; i <= MAX_OPEN; i = i + 1) begin\n              for (j = 0; j <= MAX_OPEN; j = j + 1) begin\n                dp[i][j] <= (i == 0 && j == 0) ? 16'd0 : INF;\n              end\n            end\n            state <= PROCESS;\n          end\n        end\n\n        PROCESS: begin\n          if (flight_index < flight_count) begin\n            for (i = 0; i <= MAX_OPEN; i = i + 1) begin\n              for (j = 0; j <= MAX_OPEN; j = j + 1) begin\n                new_dp[i][j] = INF;\n              end\n            end\n\n            for (i = 0; i <= MAX_OPEN; i = i + 1) begin\n              for (j = 0; j <= MAX_OPEN; j = j + 1) begin\n                if (dp[i][j] != INF) begin\n                  if (flight_seq[flight_index] == 1'b0) begin // 1->2 flight\n                    // 1. One-way ticket\n                    if (dp[i][j] + price_ow_12 < new_dp[i][j]) \n                      new_dp[i][j] = dp[i][j] + price_ow_12;\n\n                    // 2. Use open return trip from 2->1\n                    if (j > 0) begin\n                      if (dp[i][j] < new_dp[i][j-1])\n                        new_dp[i][j-1] = dp[i][j];\n                    end\n\n                    // 3. Start new round trip 1->2\n                    if (i < MAX_OPEN) begin\n                      if (dp[i][j] + price_rt_12 < new_dp[i+1][j])\n                        new_dp[i+1][j] = dp[i][j] + price_rt_12;\n                    end\n                  end else begin // 2->1 flight\n                    // 1. One-way ticket\n                    if (dp[i][j] + price_ow_21 < new_dp[i][j])\n                      new_dp[i][j] = dp[i][j] + price_ow_21;\n\n                    // 2. Use open return trip from 1->2\n                    if (i > 0) begin\n                      if (dp[i][j] < new_dp[i-1][j])\n                        new_dp[i-1][j] = dp[i][j];\n                    end\n\n                    // 3. Start new round trip 2->1\n                    if (j < MAX_OPEN) begin\n                      if (dp[i][j] + price_rt_21 < new_dp[i][j+1])\n                        new_dp[i][j+1] = dp[i][j] + price_rt_21;\n                    end\n                  end\n                end\n              end\n            end\n\n            for (k = 0; k <= MAX_OPEN; k = k + 1) begin\n              dp[k][0] <= new_dp[k][0];\n              dp[k][1] <= new_dp[k][1];\n              dp[k][2] <= new_dp[k][2];\n              dp[k][3] <= new_dp[k][3];\n              dp[k][4] <= new_dp[k][4];\n              dp[k][5] <= new_dp[k][5];\n              dp[k][6] <= new_dp[k][6];\n              dp[k][7] <= new_dp[k][7];\n              dp[k][8] <= new_dp[k][8];\n            end\n\n            flight_index <= flight_index + 3'd1;\n          end else begin\n            state <= DONE_STATE;\n            result <= dp[0][0];\n          end\n        end\n\n        DONE_STATE: begin\n          done <= 1'b1;\n          state <= IDLE;\n        end\n\n        default: state <= IDLE;\n      endcase\n    end\n  end\nendmodule